import os
from azure.ai.vision.imageanalysis import ImageAnalysisClient
from azure.ai.translation.text import TextTranslationClient, TranslatorCredential
from azure.ai.contentsafety import ContentSafetyClient
from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from openai import AzureOpenAI

def get_azure_vision_client():
    endpoint = os.environ.get("AZURE_AI_VISION_ENDPOINT")
    key = os.environ.get("AZURE_AI_VISION_KEY")
    if not endpoint or not key:
        raise ValueError("AZURE_AI_VISION_ENDPOINT and AZURE_AI_VISION_KEY environment variables must be set.")
    return ImageAnalysisClient(endpoint=endpoint, credential=AzureKeyCredential(key))

def get_document_intelligence_client():
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")
    if not endpoint or not key:
        raise ValueError("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY environment variables must be set.")
    return DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

def get_azure_translator_client():
    endpoint = os.environ.get("AZURE_TRANSLATOR_ENDPOINT")
    key = os.environ.get("AZURE_TRANSLATOR_KEY")
    region = os.environ.get("AZURE_TRANSLATOR_REGION")
    if not endpoint or not key or not region:
        raise ValueError("AZURE_TRANSLATOR_ENDPOINT, AZURE_TRANSLATOR_KEY, and AZURE_TRANSLATOR_REGION environment variables must be set.")
    return TextTranslationClient(endpoint=endpoint, credential=TranslatorCredential(key, region))

def get_azure_content_safety_client():
    endpoint = os.environ.get("AZURE_CONTENT_SAFETY_ENDPOINT")
    key = os.environ.get("AZURE_CONTENT_SAFETY_KEY")
    if not endpoint or not key:
        raise ValueError("AZURE_CONTENT_SAFETY_ENDPOINT and AZURE_CONTENT_SAFETY_KEY environment variables must be set.")
    return ContentSafetyClient(endpoint=endpoint, credential=AzureKeyCredential(key))

def get_azure_openai_client():
    endpoint = os.environ.get("AZURE_OPENAI_ENDPOINT")
    key = os.environ.get("AZURE_OPENAI_KEY")
    if not endpoint or not key:
        raise ValueError("AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_KEY environment variables must be set.")
    return AzureOpenAI(
        api_key=key,
        api_version="2024-02-01",
        azure_endpoint=endpoint
    )

from typing import List, Dict, Any

class ExtractedText:
    def __init__(self, text: str):
        self.text = text

class ExtractedLayout:
    def __init__(self, paragraphs: List[Dict[str, Any]], tables: List[Dict[str, Any]], key_values: List[Dict[str, Any]]):
        self.paragraphs = paragraphs
        self.tables = tables
        self.key_values = key_values

class ExtractedTable:
    def __init__(self, cells: List[Dict[str, Any]], rows: int, columns: int):
        self.cells = cells
        self.rows = rows
        self.columns = columns

class ExtractedKeyValue:
    def __init__(self, key: str, value: str):
        self.key = key
        self.value = value

import os
from document_client import get_azure_vision_client
from document_models import ExtractedText
from azure.ai.vision.imageanalysis import ImageAnalysisOptions, VisualFeatures

def extract_text_from_image(image_url: str) -> ExtractedText:
    client = get_azure_vision_client()

    # Select the features you want to enable
    features = [VisualFeatures.READ]

    image_analyzer = client.analyze(image_url=image_url, visual_features=features)

    # Print text content
    if image_analyzer.read is not None:
        extracted_text_content = ""
        for block in image_analyzer.read.blocks:
            for line in block.lines:
                extracted_text_content += line.text + "\n"
        return ExtractedText(text=extracted_text_content.strip())
    else:
        return ExtractedText(text="")

import os
from document_client import get_document_intelligence_client
from document_models import ExtractedLayout

def extract_layout_from_document(document_url: str) -> ExtractedLayout:
    client = get_document_intelligence_client()

    poller = client.begin_analyze_document(
        "prebuilt-layout", document_url
    )
    result = poller.result()

    paragraphs = []
    for paragraph in result.paragraphs:
        paragraphs.append({
            "content": paragraph.content,
            "bounding_regions": [{"page_number": region.page_number, "bounding_box": [p.x, p.y for p in region.bounding_regions[0].polygon]} for region in paragraph.bounding_regions] if paragraph.bounding_regions else []
        })

    tables = []
    for table in result.tables:
        cells_data = []
        for cell in table.cells:
            cells_data.append({
                "content": cell.content,
                "row_index": cell.row_index,
                "column_index": cell.column_index,
                "row_span": cell.row_span,
                "column_span": cell.column_span,
            })
        tables.append({
            "rows": table.row_count,
            "columns": table.column_count,
            "cells": cells_data,
        })

    key_values = [] # Layout model does not directly provide key-value pairs, but we keep the structure consistent.

    return ExtractedLayout(paragraphs=paragraphs, tables=tables, key_values=key_values)

import os
from document_client import get_document_intelligence_client
from document_models import ExtractedKeyValue

def extract_key_values_from_document(document_url: str) -> list[ExtractedKeyValue]:
    client = get_document_intelligence_client()

    poller = client.begin_analyze_document(
        "prebuilt-document", document_url
    )
    result = poller.result()

    extracted_key_values = []
    if result.key_value_pairs:
        for kv_pair in result.key_value_pairs:
            if kv_pair.key and kv_pair.value:
                extracted_key_values.append(
                    ExtractedKeyValue(key=kv_pair.key.content, value=kv_pair.value.content)
                )

    return extracted_key_values

import os
import json
from document_client import get_azure_openai_client

def extract_structured_fields(text: str, fields_to_extract: dict) -> dict:
    client = get_azure_openai_client()
    deployment_name = os.environ.get("AZURE_OPENAI_CHAT_DEPLOYMENT_NAME", "gpt-4") # Default to gpt-4

    # Example fields_to_extract: {"name": "string", "date_of_birth": "string (YYYY-MM-DD)"}
    field_definitions = ", ".join([f"{k}: {v}" for k, v in fields_to_extract.items()])

    prompt = f"Extract the following fields from the text below in JSON format: {field_definitions}.\n\nText: {text}\n\nJSON:"

    response = client.chat.completions.create(
        model=deployment_name,
        messages=[
            {"role": "system", "content": "You are an AI assistant that extracts structured fields from text."},
            {"role": "user", "content": prompt}
        ],
        temperature=0.0
    )

    try:
        extracted_json = json.loads(response.choices[0].message.content)
        return extracted_json
    except json.JSONDecodeError:
        return {"error": "Could not parse JSON response from OpenAI", "raw_response": response.choices[0].message.content}
